algorithms.pseudocode:
function PaleyTypeII(q):
    F <- GF(q)
    squares <- {a^2 : a in F*, a != 0}
    chi(x) <- 0 if x=0, 1 if x in squares, -1 otherwise
    Q <- [chi(e_i - e_j)] for i,j in F  (Jacobsthal matrix)
    C <- [[0, 1^T], [1, Q]]  (conference matrix)
    I <- identity(q+1)
    H <- [[C+I, C-I], [C-I, -(C+I)]]
    return H  // Hadamard matrix of order 2(q+1)

function HadamardCode(H):
    // Input: n x n Hadamard matrix
    // Output: binary code with 2n codewords, distance n/2
    code <- rows(H) union rows(-H)
    return map(x -> (1-x)/2, code)

function PaleyTournament(p):
    // Input: prime p = 3 mod 4
    // Output: doubly regular tournament matrix
    QR <- {a^2 mod p : a in 1..p-1}
    T[i,j] <- 1 if (j-i) mod p in QR, 0 otherwise
    return T
